import * as OpenAIModule from 'openai';
import config from '../lib/config';

const {OPENAI_API_KEY} = config;

const classifications = [
  'religion',
  'illegal drug use',
  'threat',
  'high risk of physical harm',
  'adult',
  'profanity',
  'racist',
  'gibberish',
  'non-english',
  'mostly capital letters',
  'names',
  'persons',
];
const prompt = `Classify if text contains ${classifications.join(
  ',',
)}. Answer with unique lower case comma separated, without space between classifications. Answer with none when nothing matches.`;

const OpenAIModuleAny = OpenAIModule as any;

let openAi: any;

if ('OpenAIApi' in OpenAIModuleAny) {
  // Mock test environment (v3 mock)
  const Configuration = OpenAIModuleAny.Configuration;
  const OpenAIApi = OpenAIModuleAny.OpenAIApi;
  const configuration = new Configuration({
    apiKey: OPENAI_API_KEY,
  });
  openAi = new OpenAIApi(configuration);
} else {
  // Real v4 environment
  const OpenAIClass = OpenAIModuleAny.default || OpenAIModuleAny.OpenAI;
  openAi = new OpenAIClass({
    apiKey: OPENAI_API_KEY,
  });
}

export const classifyText = async (text: string) => {
  let content: string | null | undefined;

  if (typeof openAi.createChatCompletion === 'function') {
    const completion = await openAi.createChatCompletion({
      model: 'gpt-4-0613', //'gpt-3.5-turbo-0613',
      temperature: 0, // Lower = less random, more deterministic
      messages: [
        {role: 'system', content: prompt},
        {role: 'user', content: text},
      ],
    });
    content = completion?.data?.choices?.[0]?.message?.content;
  } else {
    const completion = await openAi.chat.completions.create({
      model: 'gpt-4-0613', //'gpt-3.5-turbo-0613',
      temperature: 0, // Lower = less random, more deterministic
      messages: [
        {role: 'system', content: prompt},
        {role: 'user', content: text},
      ],
    });
    content = completion?.choices?.[0]?.message?.content;
  }

  return content && content !== 'none' ? content?.split(',') : null;
};

